 22: @Repository
 23: public class JdbcJ3CollectionStore implements J3CollectionStore {
 24:     private static final JsonMapper JSON = JsonMapper.builder().build();
 25:     private final NamedParameterJdbcTemplate jdbc;
 26:     public JdbcJ3CollectionStore(NamedParameterJdbcTemplate jdbc) { this.jdbc = jdbc; }
