 61:     @Override @Transactional
 62:     public void publish(Proof proof, List<Entry> entries) {
 63:         // Shared with admission: a manual success committed before a daily claim prevents its dispatch.
 64:         jdbc.queryForObject("select pg_advisory_xact_lock(-6060)",Map.of(),Object.class);
 65:         var p = params(proof.runId()).addValue("state", proof.state().name())
 66:                 .addValue("finish", ts(proof.finishedAt())).addValue("code", proof.terminalCode())
 67:                 .addValue("date", proof.date());
 68:         String state = jdbc.queryForObject("select state from j3_collection_run where run_id=:id for update", p, String.class);
 69:         if (!"RUNNING".equals(state)) {
 70:             var existing = find(proof.runId()).orElseThrow();
 71:             // JSONB compares timestamps/metadata independent of Java map iteration order.
 72:             Proof normalized = new Proof(proof.runId(),proof.date(),proof.trigger(),micros(proof.startedAt()),
 73:                     micros(proof.finishedAt()),proof.state(),proof.terminalCode(),proof.pages());
 74:             if (!existing.proof().equals(normalized) || !new java.util.HashSet<>(existing.entries()).equals(new java.util.HashSet<>(entries)))
 75:                 throw new IllegalStateException("J3_TERMINAL_IDENTITY_CONFLICT");
 76:             return;
 77:         }
 78:         var row = jdbc.queryForMap("select collection_date,trigger_kind,started_at from j3_collection_run where run_id=:id", p);
 79:         if (!row.get("collection_date").toString().equals(proof.date().toString())
 80:                 || !row.get("trigger_kind").equals(proof.trigger().name())
 81:                 || !((Timestamp) row.get("started_at")).toInstant().equals(micros(proof.startedAt())))
 82:             throw new IllegalStateException("J3_RUN_IDENTITY_CONFLICT");
 83:         for (var page : proof.pages()) appendPage(proof.runId(), page);
 84:         if (jdbc.queryForObject("select count(*) from j3_collection_page where run_id=:id", p, Integer.class) != proof.pages().size())
 85:             throw new IllegalStateException("J3_PAGE_COUNT_MISMATCH");
 86:         if (!proof.successful() && !entries.isEmpty()) throw new IllegalArgumentException("J3_FAILED_CATALOGUE");
 87:         if (proof.successful()) {
 88:             List<Boolean> rawPresent = jdbc.query("""
 89:                     select s.payload_raw is not null from provider_snapshot s join j3_collection_page p on p.snapshot_id=s.id
 90:                     where p.run_id=:id for share of s
 91:                     """, p, (rs, n) -> rs.getBoolean(1));
 92:             if (rawPresent.size() != proof.pages().size() || rawPresent.contains(false))
 93:                 throw new IllegalStateException("J3_RAW_EVIDENCE_UNAVAILABLE");
 94:             for (Entry entry : entries) {
 95:                 jdbc.update("insert into j3_catalog_entry(run_id,tournament_id,entry) values (:id,:t,cast(:json as jsonb))",
 96:                         params(proof.runId()).addValue("t", entry.tournamentId()).addValue("json", JSON.writeValueAsString(entry)));
 97:                 for (Long snapshot : entry.sourceSnapshotIds()) {
 98:                     int page = proof.pages().stream().filter(it -> snapshot.equals(it.snapshotId())).findFirst()
 99:                             .orElseThrow(() -> new IllegalArgumentException("J3_ENTRY_SOURCE_MISMATCH")).page();
100:                     jdbc.update("insert into j3_catalog_source(run_id,tournament_id,page) values (:id,:t,:page)",
101:                             params(proof.runId()).addValue("t", entry.tournamentId()).addValue("page", page));
102:                 }
103:             }
104:         }
105:         jdbc.update("update j3_collection_run set state=:state,finished_at=:finish,terminal_code=:code where run_id=:id", p);
106:         if (proof.successful()) {
107:             jdbc.update("""
108:                     insert into j3_last_success(collection_date,run_id,revision) values (:date,:id,1)
109:                     on conflict (collection_date) do update set run_id=excluded.run_id,revision=j3_last_success.revision+1
110:                     where (select finished_at from j3_collection_run where run_id=j3_last_success.run_id) <= :finish
111:                     """, p);
112:         }
113:     }
