149:         var ids = jdbc.query("""
150:                 select l.run_id from j3_last_success l join j3_collection_run r on r.run_id=l.run_id
151:                 where l.collection_date=:date and not exists (select 1 from j3_legacy_recovery h
152:                     where h.collection_date=:date and h.status='SUCCESS_PROVEN_CONTENT_UNAVAILABLE' and h.finished_at>r.finished_at)
153:                 """, Map.of("date",date), (rs,n) -> rs.getObject(1,UUID.class));
154:         return ids.isEmpty() ? Optional.empty() : find(ids.getFirst());
