164:                 select exists(select 1 from j3_last_success where collection_date=:date)
165:                     or exists(select 1 from j8_benchmark_campaign c join j8_benchmark_campaign_result r using(campaign_id)
166:                         where c.campaign_type='J3_SCHEDULED_EVENTS' and c.collection_date=:date and r.terminal_state='COMPLETED')
