169:     @Override
170:     public List<DateSummary> dates(int limit) {
171:         if (limit < 1 || limit > 3660) throw new IllegalArgumentException("J3_DATE_LIMIT");
172:         return jdbc.query("""
173:                 select distinct on (collection_date) collection_date,run_id,finished_at,status from (
174:                     select r.collection_date,r.run_id,r.finished_at,'AVAILABLE' status from j3_last_success l
175:                         join j3_collection_run r on r.run_id=l.run_id
176:                     union all select collection_date,null::uuid,finished_at,status from j3_legacy_recovery
177:                         where status='SUCCESS_PROVEN_CONTENT_UNAVAILABLE'
178:                 ) d order by collection_date desc,finished_at desc,run_id nulls last limit :limit
179:                 """, Map.of("limit",limit), (r,n) -> new DateSummary(r.getObject(1,LocalDate.class),
180:                 r.getObject(2,UUID.class),r.getTimestamp(3).toInstant(),r.getString(4)));
