  71:     public Optional<CompletableFuture<J3CollectionExecutor.Result>> submitJ3(Order order, J3Work work) {
  72:         Session s=active.get();
  73:         if(s==null) return Optional.empty();
  74:         s.dispatchLock.lock();
  75:         try {
  76:             if(s.finished || s.stopReason!=null || s.ownership==null || s.schedule==null)
  77:                 throw new IllegalStateException("J3_LIVE_UNAVAILABLE");
  78:             if(!"live-v11".equals(s.manifest.policyVersion()) || j3Pauses==null)
  79:                 throw new IllegalStateException("J3_LIVE_POLICY_UNSUPPORTED");
  80:             if(s.j3!=null) throw new IllegalStateException("J3_LIVE_BUSY");
  81:             Instant deadline=order.deadline().isBefore(s.timeOrigin.plus(s.manifest.duration()))
  82:                     ?order.deadline():s.timeOrigin.plus(s.manifest.duration());
  83:             if(!clock.instant().plusSeconds(130).isBefore(deadline))
  84:                 throw new IllegalStateException("J3_LIVE_DEADLINE_TOO_CLOSE");
  85:             J3Handoff handoff=new J3Handoff(order,deadline,work);
  86:             // A lost SQL response must keep emission excluded until full live cleanup.
  87:             s.j3=handoff;
  88:             try { j3Pauses.request(order.id(),s.ownership,clock.instant(),deadline); }
  89:             catch(RuntimeException failure) {
  90:                 s.stopAll("STOPPED_ERROR"); handoff.future.completeExceptionally(failure); throw failure;
